const normalizeSvg = (svgString: string, className: string): string => {
  return svgString.replace(
    /<svg\b([^>]*)>/i,
    `<svg class="${className}" style="display:inline-block;vertical-align:middle;" $1>`
  );
};

export const PLATFORM_LOGOS: Record<string, PlatformBrandDefinition> = Object.values(
  SVGL_BRAND_LOGOS
).reduce((acc, brand) => {
  acc[brand.id] = {
    id: brand.id,
    name: brand.name,
    category: brand.category,
    color: brand.color,
    source: brand.source,
    svg: ({ className = "w-4 h-4 shrink-0", isDark = false }) => {
      const rawSvg = isDark ? brand.svgDark : brand.svgLight;
      const html = normalizeSvg(rawSvg, className);
      return (
        <span
          className={`inline-flex items-center justify-center shrink-0 overflow-hidden leading-none select-none ${className} [&>svg]:w-full [&>svg]:h-full [&>svg]:max-w-full [&>svg]:max-h-full`}
          dangerouslySetInnerHTML={{ __html: html }}
        />
      );
    },
  };
  return acc;
}, {} as Record<string, PlatformBrandDefinition>);

